@theme {
  --default-transition-duration: 220ms;
  --default-transition-timing-function: cubic-bezier(.2, .7, .2, 1);
  --color-paper: #f4f1e9;
  --color-ink: #20201d;
  --color-muted: #656158;
  --color-line: #d2ccc0;
  --color-control: #898d80;
  --color-surface: #e8e3d8;
  --color-card: #faf8f2;
  --color-terracotta: #ac4333;
  --color-gold: #edbd52;
  --color-danger: #a32925;
  --color-on-danger: #ffffff;
  --color-success: #326145;
  --color-chart-3: #b4bdb0;
  --color-chart-4: #cfc5ad;
  --color-chart-5: #8b9fa2;
  --radius-lg: 9px;
  --radius-xl: 16px;
  --radius-2xl: 22px;
  --font-sans: "DM Sans Variable", Arial, sans-serif;
  --font-editorial: "Lora Variable", Georgia, serif;
}
@layer base {
  * {
    border-color: var(--color-line);
  }
  body {
    background: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
    margin: 0;
    -webkit-font-smoothing: antialiased;
  }
  button:not(:disabled),
  summary {
    cursor: pointer;
  }
  :focus-visible {
    outline: 2px solid var(--color-terracotta);
    outline-offset: 4px;
  }
}
.a-scroll-track { width: 14px; padding: 16px 4px; background: transparent; touch-action: none; user-select: none; }
.a-scroll-thumb { min-height: 32px; border-radius: 999px; background: color-mix(in srgb, var(--color-muted) 32%, transparent); transition: background-color var(--motion-normal) var(--motion-ease); }
.a-scroll-track:hover .a-scroll-thumb, .a-scroll-thumb:active { background: color-mix(in srgb, var(--color-muted) 72%, transparent); }
/* Native scroll surfaces inside components share the ScrollArea thumb: a 6px pill on a transparent track. */
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar { width: 12px; height: 12px; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-track { background: transparent; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb { border: 3px solid transparent; border-radius: 999px; background: color-mix(in srgb, var(--color-muted) 32%, transparent); background-clip: padding-box; min-height: 32px; }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb:hover, :is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-thumb:active { background-color: color-mix(in srgb, var(--color-muted) 72%, transparent); }
:is(.a-scrollbar, .a-popup, .a-modal-content)::-webkit-scrollbar-corner { background: transparent; }
@supports not selector(::-webkit-scrollbar) {
  :is(.a-scrollbar, .a-popup, .a-modal-content) { scrollbar-width: thin; scrollbar-color: color-mix(in srgb, var(--color-muted) 32%, transparent) transparent; }
}
@layer components {
  .a-card{
    padding:var(--space-card,24px);
    border:var(--card-border-width,1px) solid var(--color-card-border,var(--color-line));
    border-top-width:var(--card-top-width,1px);
    box-shadow:var(--shadow-card,none);
  }
  .a-button {
    @apply inline-flex shrink-0 items-center justify-center gap-2 rounded-lg font-medium transition-[background-color,color,border-color,box-shadow,transform] disabled:pointer-events-none disabled:opacity-45 focus-visible:outline-2 focus-visible:outline-offset-4 active:translate-y-px;
    letter-spacing: -0.015em;
    max-width: 100%;
    white-space: normal;
    overflow-wrap: anywhere;
  }
  .a-input {
    @apply min-h-10 w-full rounded-lg border border-line bg-paper/50 px-3 py-2 text-sm text-ink shadow-xs placeholder:text-muted/75 disabled:opacity-50 read-only:bg-surface/70 read-only:shadow-none read-only:focus-visible:bg-surface/70 aria-invalid:border-danger focus-visible:bg-card transition-colors;
  }
  .a-overlay {
    @apply fixed inset-0 z-50 bg-black/40 backdrop-blur-xs;
  }
  .a-popup {
    @apply z-50 rounded-xl border border-line bg-card p-2 text-ink shadow-xl;
    max-width: calc(100vw - 24px);
    max-height: min(
      80dvh,
      var(--radix-popover-content-available-height, 80dvh)
    );
    overflow-y: auto;
    overscroll-behavior: contain;
    background: var(--color-menu, var(--color-card));
  }
}
.a-modal-content {
  overflow-wrap: anywhere;
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
.a-input {
  min-width: 0;
}
.a-calendar {
  --cal-radius: 10px;
  --cal-target: 44px;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
  color: var(--color-ink);
  width: 100%;
  max-width: 100%;
  --rdp-accent-color: var(--color-terracotta);
}
.a-calendar .rdp-months {
  display: flex;
  flex-wrap: wrap;
  gap: 32px;
  align-items: start;
}
.a-calendar .rdp-month {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  flex: 1 1 260px;
  min-width: 0;
  gap: 10px 8px;
  /* Zoomed text may need more than the parent width; the month then scrolls as a bounded region instead of overlapping digits. */
  overflow-x: auto;
}
.a-calendar .rdp-month_caption {
  flex: 1 1 auto;
  min-width: 0;
  padding-inline-start: 6px;
  font-family: var(--font-editorial);
  font-size: 1.125rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  overflow-wrap: break-word;
}
.a-calendar .rdp-caption_label {
  line-height: 1.4;
}
.a-calendar .rdp-nav {
  display: flex;
  gap: 6px;
  margin: 0;
  margin-inline-start: auto;
}
.a-calendar .rdp-month_grid {
  flex: 1 0 100%;
  border-collapse: separate;
  border-spacing: 0 2px;
  width: 100%;
  table-layout: auto;
}
.a-calendar th {
  width: 14.28%;
  min-width: 1.75em;
  height: 36px;
  color: var(--color-muted);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: center;
  white-space: nowrap;
}
.a-calendar td {
  width: 14.28%;
  min-width: 1.75em;
  height: var(--cal-target);
  padding: 0;
  text-align: center;
}
.a-calendar .rdp-week_number {
  width: auto;
  min-width: 1.5em;
  padding-inline-end: 6px;
  color: var(--color-muted);
  font-size: 0.6875rem;
  letter-spacing: 0.04em;
}
.a-calendar button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-width: 24px;
  min-height: var(--cal-target);
  border: 1px solid transparent;
  border-radius: var(--cal-radius);
  color: inherit;
  background: transparent;
  font: inherit;
  line-height: 1;
  touch-action: manipulation;
  transition:
    background-color var(--motion-fast, 140ms) var(--motion-ease, ease-out),
    color var(--motion-fast, 140ms) var(--motion-ease, ease-out),
    border-color var(--motion-fast, 140ms) var(--motion-ease, ease-out);
}
.a-calendar button:hover:not(:disabled):not([aria-disabled="true"]) {
  background: var(--color-surface);
}
.a-calendar button:focus-visible {
  outline-offset: -3px;
  z-index: 1;
}
.a-calendar [data-today="true"] button {
  font-weight: 600;
}
.a-calendar [data-today="true"] button::after {
  content: "";
  position: absolute;
  bottom: 6px;
  left: 50%;
  width: 4px;
  height: 4px;
  border-radius: 999px;
  background: var(--color-terracotta);
  translate: -50% 0;
}
.a-calendar [data-outside="true"] button {
  color: color-mix(in srgb, var(--color-muted) 65%, transparent);
}
.a-calendar [aria-selected="true"] button {
  background: var(--color-ink);
  color: var(--color-paper);
}
.a-calendar [aria-selected="true"] button::after {
  background: var(--color-paper);
}
.a-calendar [aria-selected="true"] button:hover:not(:disabled) {
  background: var(--color-ink);
}
.a-calendar .rdp-range_middle {
  background: var(--color-surface);
}
.a-calendar .rdp-range_middle button {
  background: transparent;
  color: var(--color-ink);
  border-radius: 0;
}
.a-calendar .rdp-range_middle button::after {
  background: var(--color-terracotta);
}
.a-calendar .rdp-range_middle button:hover:not(:disabled) {
  background: color-mix(in srgb, var(--color-ink) 8%, var(--color-surface));
}
.a-calendar .rdp-range_start:not(.rdp-range_end) {
  background: linear-gradient(to right, transparent 50%, var(--color-surface) 50%);
}
.a-calendar .rdp-range_end:not(.rdp-range_start) {
  background: linear-gradient(to left, transparent 50%, var(--color-surface) 50%);
}
.a-calendar[dir="rtl"] .rdp-range_start:not(.rdp-range_end) {
  background: linear-gradient(to left, transparent 50%, var(--color-surface) 50%);
}
.a-calendar[dir="rtl"] .rdp-range_end:not(.rdp-range_start) {
  background: linear-gradient(to right, transparent 50%, var(--color-surface) 50%);
}
.a-calendar tr > .rdp-range_middle:first-child,
.a-calendar tr > .rdp-week_number + .rdp-range_middle {
  border-start-start-radius: var(--cal-radius);
  border-end-start-radius: var(--cal-radius);
}
.a-calendar .rdp-hidden,
.a-calendar .rdp-hidden.rdp-range_start,
.a-calendar .rdp-hidden.rdp-range_middle,
.a-calendar .rdp-hidden.rdp-range_end {
  background: transparent;
}
.a-calendar tr > .rdp-range_middle:last-child {
  border-start-end-radius: var(--cal-radius);
  border-end-end-radius: var(--cal-radius);
}
.a-calendar button:disabled,
.a-calendar button[aria-disabled="true"] {
  color: var(--color-muted);
  opacity: 0.45;
  cursor: default;
}
.a-calendar .rdp-button_previous,
.a-calendar .rdp-button_next {
  width: 40px;
  height: 40px;
  min-height: 40px;
  border-color: var(--color-line);
  border-radius: 999px;
  color: var(--color-ink);
  flex-shrink: 0;
}
.a-calendar .rdp-button_previous:hover:not(:disabled),
.a-calendar .rdp-button_next:hover:not(:disabled) {
  border-color: var(--color-control);
  background: var(--color-card);
}
.a-calendar svg {
  width: 14px;
  height: 14px;
  fill: currentColor;
}
.a-calendar .rdp-dropdowns {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  align-items: center;
  min-width: 0;
}
.a-calendar .rdp-dropdown_root {
  position: relative;
  display: inline-flex;
  flex: 1 1 8.5rem;
  max-width: 100%;
  min-width: 0;
}
.a-calendar .rdp-dropdown_root:has(> .rdp-years_dropdown) {
  flex: 0 1 6rem;
}
.a-calendar .rdp-dropdown_root > .rdp-caption_label {
  display: none;
}
.a-calendar .rdp-dropdown_root::after {
  content: "";
  position: absolute;
  inset-inline-end: 13px;
  top: calc(50% - 5px);
  width: 7px;
  height: 7px;
  border-inline-end: 1.5px solid var(--color-muted);
  border-block-end: 1.5px solid var(--color-muted);
  rotate: 45deg;
  pointer-events: none;
}
.a-calendar .rdp-dropdown {
  appearance: none;
  min-height: 40px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  padding: 4px 30px 4px 12px;
  border: 1px solid var(--color-line);
  border-radius: var(--cal-radius);
  color: var(--color-ink);
  background: color-mix(in srgb, var(--color-paper) 50%, transparent);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--color-ink) 4%, transparent);
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: background-color var(--motion-fast, 140ms) var(--motion-ease, ease-out), border-color var(--motion-fast, 140ms) var(--motion-ease, ease-out);
}
.a-calendar .rdp-dropdown:hover {
  border-color: var(--color-control);
}
.a-calendar .rdp-dropdown:focus-visible {
  background: var(--color-card);
}
.a-calendar[dir="rtl"] .rdp-dropdown {
  padding: 4px 12px 4px 30px;
}
.a-calendar .rdp-month:has(> .rdp-button_previous) > .rdp-month_caption,
.a-calendar .rdp-month:has(> .rdp-button_next) > .rdp-month_caption {
  text-align: center;
  padding-inline-start: 0;
}
.a-calendar .rdp-footer {
  margin-top: 6px;
  padding-top: 12px;
  border-top: 1px solid var(--color-line);
  color: var(--color-muted);
  font-size: 0.8125rem;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
@media (prefers-reduced-motion: reduce) {
  .a-calendar button {
    transition: none;
  }
}
@media (max-width: 640px), (pointer: coarse) {
  .a-button {
    min-height: 44px;
    min-width: 44px;
  }
  .a-input {
    min-height: 44px;
    font-size: 16px;
  }
  [role="tab"],
  [role="menuitem"] {
    min-height: 44px;
  }
}
[data-theme="dark"] {
  --color-paper: #191a18;
  --color-ink: #eeeade;
  --color-muted: #b8b3a8;
  --color-line: #45463f;
  --color-control: #7b8371;
  --color-surface: #30312c;
  --color-card: #22241f;
  --color-terracotta: #e69477;
  --color-danger: #f2938c;
  --color-on-danger: #28120f;
  --color-success: #8fc8a4;
  --color-chart-3: #788b76;
  --color-chart-4: #a99b77;
  --color-chart-5: #7d9ca2;
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

/* Shared motion travels with installed components. */
:root {
  --motion-fast: 140ms;
  --motion-normal: 220ms;
  --motion-enter: 280ms;
  --motion-exit: 180ms;
  --motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --motion-settle: cubic-bezier(0.2, 0.7, 0.2, 1);
}
@layer components {
  :where(
    .a-button,
    .a-input,
    .a-close,
    [role="switch"],
    [role="checkbox"],
    [role="radio"],
    [role="tab"],
    [role="menuitem"],
    [role="option"],
    .a-calendar button
  ) {
    transition-duration: var(--motion-normal);
    transition-timing-function: var(--motion-settle);
    transition-property:
      background-color, color, border-color, box-shadow, opacity;
  }
  [role="switch"] > span {
    transition-duration: var(--motion-normal);
    transition-timing-function: var(--motion-ease);
  }
  .a-overlay[data-state="open"] {
    animation: a-fade-in var(--motion-enter) var(--motion-ease);
  }
  .a-overlay[data-state="closed"] {
    animation: a-fade-out var(--motion-exit) ease-in;
  }
  :where(.a-modal-content, .a-popup, .a-tooltip, .a-toast)[data-state="open"],
  .a-tooltip[data-state="delayed-open"] {
    animation: a-enter var(--motion-enter) var(--motion-ease);
  }
  :where(
    .a-modal-content,
    .a-popup,
    .a-tooltip,
    .a-toast
  )[data-state="closed"] {
    animation: a-exit var(--motion-exit) ease-in;
  }
  .a-accordion-content {
    overflow: hidden;
  }
  .a-accordion-content[data-state="open"] {
    animation: a-expand var(--motion-enter) var(--motion-ease);
  }
  .a-accordion-content[data-state="closed"] {
    animation: a-collapse var(--motion-exit) var(--motion-settle);
  }
  .a-accordion-trigger svg {
    transition: rotate var(--motion-normal) var(--motion-ease);
  }
  .a-accordion-trigger[data-state="open"] svg {
    rotate: 90deg;
  }
  .a-collapsible[data-state="open"],
  .a-tabs-content[data-state="active"] {
    animation: a-fade-in var(--motion-normal) var(--motion-ease);
  }
  .animate-pulse {
    animation-duration: 2.8s;
  }
  .animate-spin {
    animation-duration: 1.2s;
  }
}
/* Transform leaves positional translate utilities intact on centered dialogs. */
@keyframes a-enter {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.99);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@keyframes a-exit {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
    transform: translateY(3px) scale(0.995);
  }
}
@keyframes a-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes a-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes a-expand {
  from {
    height: 0;
    opacity: 0;
  }
  to {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
}
@keyframes a-collapse {
  from {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
  to {
    height: 0;
    opacity: 0;
  }
}

/* Opt-in surface treatments. Decoration never intercepts interaction. ScrollArea fades live in scroll-fade.css. */
.a-edge-fade {
  position: relative;
  isolation: isolate;
}
.a-edge-fade::after {
  content: "";
  position: absolute;
  z-index: 1;
  inset-inline: 0;
  bottom: 0;
  height: min(var(--fade-depth, 260px), 35%);
  pointer-events: none;
  background: linear-gradient(to bottom, transparent, var(--color-paper));
  opacity: 1;
  transition: opacity var(--motion-normal, 220ms) var(--motion-ease, ease-out);
}
@media (hover: hover) and (pointer: fine) {
  .a-surface-lift:hover {
    border-color: var(--color-muted);
    box-shadow:
      0 2px 4px color-mix(in srgb, var(--color-ink) 4%, transparent),
      0 12px 28px color-mix(in srgb, var(--color-ink) 6%, transparent);
    translate: 0 -2px;
  }
}
.a-surface-lift {
  transition:
    border-color var(--motion-normal, 220ms),
    box-shadow var(--motion-enter, 280ms) var(--motion-ease, ease-out),
    translate var(--motion-normal, 220ms) var(--motion-ease, ease-out);
}
@media (prefers-reduced-motion: reduce) {
  .a-edge-fade::after,
  .a-surface-lift {
    transition: none;
  }
  .a-surface-lift:hover {
    translate: none;
  }
}
@media (forced-colors: active) {
  .a-edge-fade::after {
    display: none;
  }
}
